package main

func addDashboardResourceSchema(result map[string]any, routes map[string][]string) {
	result["commands"] = append(result["commands"].([]string), "folders list", "folders get --id UID", "folders create --id UID --name TITLE [--parent-uid UID]", "folders save --file FILE|- [--id UID] (update requires version)", "folders move --id UID [--parent-uid UID]", "folders delete --id UID [--force-delete-rules]", "library list [--query TEXT --folder-uid UID --limit 100]", "library get|model|connections --id UID", "library save --file FILE|- [--id UID] (update requires version)", "library delete --id UID", "dashboards move --id ID [--folder-uid UID --revision UPDATED_AT]", "dashboards library-add --id ID --library-uid UID [--revision UPDATED_AT]", "dashboards library-unlink --id ID --panel NATIVE_PANEL_ID [--revision UPDATED_AT]", "api --path API_ROUTE [--method GET|POST|PUT|PATCH|DELETE --file FILE|-]")
	routes["GET"] = append(routes["GET"], "/api/v1/folders", "/api/folders", "/api/folders/{uid}", "/api/folders/{uid}/parents", "/api/library-elements", "/api/library-elements/{uid}", "/api/library-elements/name/{name}", "/api/library-elements/{uid}/connections", "/api/v1/library-models/{uid}", "/api/gnet/plugins", "/api/gnet/plugins/{id}", "/api/gnet/plugins/{id}/versions", "/api/gnet/plugins/{id}/versions/{version}", "/api/plugins/{id}/markdown/{name}", "/api/plugins/errors", "/api/gnet/dashboards/{id}", "/api/plugins/{id}/dashboards")
	routes["POST"] = append(routes["POST"], "/api/folders", "/api/folders/{uid}/move", "/api/library-elements", "/api/v1/dashboard-library/{id}", "/api/v1/dashboard-library/{id}/unlink", "/api/plugins/{id}/install", "/api/plugins/{id}/uninstall", "/api/dashboards/interpolate", "/api/dashboards/import")
	routes["PUT"] = append(routes["PUT"], "/api/folders/{uid}", "/api/v1/dashboard-folders/{id}")
	routes["PATCH"] = append(routes["PATCH"], "/api/library-elements/{uid}")
	routes["DELETE"] = append(routes["DELETE"], "/api/folders/{uid}", "/api/library-elements/{uid}")
	result["folders"] = map[string]any{"tree": "nested folders; complete tree at /api/v1/folders, children at /api/folders?parentUid=UID", "versions": "Grafana update requires version or overwrite; cycle and sibling-name collisions rejected", "deletion": "atomic descendants, dashboards and unused library panels; connected libraries and system dashboard block deletion; alert rules require forceDeleteRules and share scheduler mutation gates", "identity": "stable numeric dashboard and folder IDs allocated locally and retained after restart", "pending": []string{"folder RBAC and repository provisioning", "App Platform folder resource API"}}
	result["library_panels"] = map[string]any{"contract": "Grafana library-elements API, kind=1; JSON model, version, folder and live dashboard connections", "execution": "shared query and visualization model resolved on reads; edits propagate to all linked instances; unlink captures latest model", "import": "Classic/V1/V2 exported __elements definitions and dashboard commit together; V2 LibraryPanel references retained in exports", "precision": "raw model endpoint and atomic move/insert/unlink preserve opaque JSON numbers", "snapshots": "library references detached when frozen snapshots are captured", "pending": []string{"library UID rename", "App Platform library resources"}}
	result["api_cli"] = map[string]any{"scope": "all published API routes support agent calls through api --path", "text": "non-JSON responses return JSON content/contentType", "body": "--file sends original JSON; omitted file sends no body", "authentication": "same server/token options as typed commands"}
}
